-- =============================================================================
-- 0029_repair_tamil_step_titles.sql
--
-- GENERATED by scripts/build-title-repair.mjs. Do not hand-edit.
--
-- 0025 wrote the Tamil MANTRA into step_title_ta on twelve of the thirteen
-- steps it added. The generator did
--     const o = { ...s }; Object.assign(o, scripts(s.deva.join(chr(10))));
-- and scripts() returns a key called `ta` for the mantra, which landed on top
-- of the step’s own `ta`, its title. The archana step has no mantra and so was
-- the only one left intact.
--
-- Nothing caught it because every gate was checking the VALUE and none was
-- checking what KIND of value it was: a Tamil mantra is well-formed Tamil, it
-- is not null, and it is not truncated. It surfaced when the step-jump dropdown
-- started reading "Step 10: shuklaambaradharam viSHNum...".
--
-- 0025 is fixed at source; this repairs a database that already ran it.
--
-- Idempotent, and guarded: it only touches a title that is still mantra-shaped,
-- so a hand-corrected title is never overwritten.
-- =============================================================================

begin;

update public.pooja_steps set step_title_ta = 'விக்னேஸ்வர சங்கல்பம்', updated_at = now()
 where pooja_id = 'ganesha_standard' and step_title_en = 'Vighneshwara Sankalpam'
   and (length(step_title_ta) > 60 or step_title_ta like '%' || chr(10) || '%'
        or step_title_ta like '%।%' or step_title_ta is null);
